"""Generate bilingual user documentation from one maintained source."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'docs/content.json').read_text());history=json.loads((root/'includes/history.json').read_text())
for lang,d in data.items():
 de=lang=='de';other='README.md' if de else 'README-de.md';labels={'new':'Neu' if de else 'New','improved':'Verbessert' if de else 'Improved','fixed':'Behoben' if de else 'Fixed','misc':'Sonstiges' if de else 'Misc'}
 change='\n\n'.join('### '+r['version']+' · '+r['date'][lang]+'\n\n'+'\n'.join('- **'+labels[i['category']]+':** '+i[lang] for i in r['items']) for r in history)
 t=d['titles'];faq='\n\n'.join('### '+q+'\n\n'+a for q,a in d['faq'])
 full=('docs/FAQ-de.md' if de else 'docs/FAQ.md')
 md='# Oxygen QuickNav\n\n'+('[English]' if de else '[Deutsch]')+'('+other+')\n\n'+('![Oxygen QuickNav](assets-github/approved/banner-'+lang+'.png)\n\n')+'## '+t[0]+'\n\n'+d['about']+'\n\n'+d['requirements']+'\n\n[FAQ](#faq) · ['+t[5]+'](#'+('änderungsverlauf' if de else 'changelog')+') · [GitHub](https://github.com/deckerweb/oxygen-quicknav)\n\n'+('**Inhalt:** ' if de else '**Contents:** ')+' · '.join('['+x+'](#'+x.lower().replace(' & ','--').replace(' ','-')+')' for x in t)+'\n\n## '+t[1]+'\n\n'+'\n'.join('- '+s for s in d['features'])+'\n\n## '+t[2]+'\n\n'+'\n'.join(str(i+1)+'. '+s for i,s in enumerate(d['install']))+'\n\n## '+t[3]+'\n\n'+('\n\n'.join('### '+s.split(';')[0]+'\n\n'+s for s in d['features']))+'\n\n## FAQ\n\n'+faq+'\n\n'+('[Fragen nach Themen]' if de else '[FAQ by topic]')+'('+full+')\n\n## '+t[5]+'\n\n'+change+'\n\n## '+t[6]+'\n\nDavid Decker – DECKERWEB. QuickNav.\n\n[Issues](https://github.com/deckerweb/oxygen-quicknav/issues) · [Security](SECURITY.md) · [Ko-fi](https://ko-fi.com/deckerweb) · [Buy Me a Coffee](https://buymeacoffee.com/daveshine) · [PayPal](https://paypal.me/deckerweb)\n\n'+('Das Plugin entstand als Fork von ' if de else 'This plugin originated as a fork of ')+'[Breakdance Navigator](https://github.com/beamkiller/breakdance-navigator), Peter Kulcsár, © 2024, GPL v2 or later.\n\nCopyright © 2025–2026 David Decker – DECKERWEB. GPL v2 or later. '+('Das bestehende Oxygen-Logo gehört Soflyy. Das neue Navigationssymbol ist eine eigene Vektorgrafik. ' if de else 'The existing Oxygen logo belongs to Soflyy. The navigation symbol is original vector artwork. ')+'deckerweb Updater 2.2.1 and Library 1.1.0: © 2026 David Decker – DECKERWEB, GPL-2.0-or-later.\n'
 (root/('README-de.md' if de else 'README.md')).write_text(md)
 grouped='\n\n'.join('## '+heading+'\n\n'+'\n\n'.join('### '+q+'\n\n'+a for q,a in d['faq'][start:end]) for heading,start,end in [(('Einstieg' if de else 'Getting started'),0,2),(('Alltag & Einstellungen' if de else 'Everyday use & settings'),2,5),(('Kompatibilität & Daten' if de else 'Compatibility & data'),5,7)])
 (root/'docs'/('FAQ-de.md' if de else 'FAQ.md')).write_text('# '+('Fragen nach Themen' if de else 'FAQ by topic')+'\n\n'+('[English](FAQ.md)' if de else '[Deutsch](FAQ-de.md)')+'\n\n'+grouped+'\n')
 (root/'docs'/('CHANGELOG-de.md' if de else 'CHANGELOG.md')).write_text('# '+t[5]+'\n\n'+('[English](CHANGELOG.md)' if de else '[Deutsch](CHANGELOG-de.md)')+'\n\n'+change+'\n')
# Directory-format source can be generated, but this GitHub build contains external updaters.
d=data['en']
readme='=== Oxygen QuickNav ===\nContributors: daveshine\nTags: oxygen, toolbar, navigation\nRequires at least: 6.7\nTested up to: 7.1\nRequires PHP: 8.1\nStable tag: 2.1.0\nLicense: GPLv2 or later\nLicense URI: https://www.gnu.org/licenses/gpl-2.0.html\n\n'+'Quick access to Oxygen and Oxygen Classic content, templates, settings, and add-ons from the WordPress toolbar.'+'\n\n== Description ==\n\n'+d['requirements']+'\n\n'+'\n'.join('* '+s for s in d['features'])+'\n\n== Installation ==\n\n'+'\n'.join(str(i+1)+'. '+s for i,s in enumerate(d['install']))+'\n\n== Frequently Asked Questions ==\n\n'+'\n\n'.join('= '+q+' =\n\n'+a for q,a in d['faq'])+'\n\n== Changelog ==\n\n'+'\n\n'.join('= '+r['version']+' =\n\n'+'\n'.join('* '+{'new':'New','improved':'Improved','fixed':'Fixed','misc':'Misc'}[i['category']]+': '+i['en'] for i in r['items']) for r in history)+'\n'
(root/'readme.txt').write_text(readme)
